import{J as e,n as t,q as n,st as r}from"./chunks/framework.dvm6fd6R.js";var i=JSON.parse(`{"title":"Research notes","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Research notes"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/research/"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/research/"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/research/README.md"}},"headers":[],"relativePath":"research/index.md","filePath":"research/index.md","lastUpdated":1794468377000}`),a={name:`research/index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<div><h1 id="research-notes" tabindex="-1">Research notes <a class="header-anchor" href="#research-notes" aria-label="Permalink to “Research notes”">​</a></h1><p>Investigations against primary sources for the data-driven vanilla effort. The plan that draws on them is <a href="/pr-preview/pr-3052/plans/data-driven-vanilla.html">docs/plans/data-driven-vanilla.md</a>. Each note cites the source of every claim and ends with the commands that reproduce it.</p><p>The first nine notes, written 2026-10-24, asked how a Bedrock server becomes data-driven. The eight that follow, written the same day, ask the narrower question the plan now turns on: whether Java Edition&#39;s data can drive a server that speaks to Bedrock clients.</p><p>The dimension notes, written 2026-10-30, ask what it takes to run the Overworld, the Nether and the End as one save with portals between them, and how to describe each dimension and its generator as data.</p><h2 id="the-bedrock-side" tabindex="-1">The Bedrock side <a class="header-anchor" href="#the-bedrock-side" aria-label="Permalink to “The Bedrock side”">​</a></h2><ul><li><a href="/pr-preview/pr-3052/research/bedrock-data-extraction.html">bedrock-data-extraction.md</a>: obtaining the Bedrock Dedicated Server automatically, what its zip contains, what is and is not data-driven in vanilla Bedrock, Mojang/bedrock-samples, licensing, peer projects, running BDS headless in CI, what this server hardcodes today.</li><li><a href="/pr-preview/pr-3052/research/bedrock-entities-spawning-loot-trading.html">bedrock-entities-spawning-loot-trading.md</a>: the entity, spawn rule, loot table and trade table grammars with vanilla usage counts and coverage curves for goals and components.</li><li><a href="/pr-preview/pr-3052/research/bedrock-blocks-items-recipes-biomes-features.html">bedrock-blocks-items-recipes-biomes-features.md</a>: the block, item, recipe, item catalog, biome, feature, feature rule, structure and voxel shape grammars, which block properties come from where, and a first grouping of all blocks and items by behavior.</li><li><a href="/pr-preview/pr-3052/research/bedrock-addons-and-custom-content.html">bedrock-addons-and-custom-content.md</a>: the two channels a Bedrock client learns custom content through, the pack container and manifest schemas, resource pack delivery and encryption, custom block, item and entity registration end to end, and what a third-party server cannot do.</li><li><a href="/pr-preview/pr-3052/research/molang.html">molang.md</a>: the Molang specification, the queries vanilla uses server-side, semantics that matter for parity, existing evaluators, and the design of one for this project.</li></ul><h2 id="the-java-side" tabindex="-1">The Java side <a class="header-anchor" href="#the-java-side" aria-label="Permalink to “The Java side”">​</a></h2><ul><li><a href="/pr-preview/pr-3052/research/java-datapacks.html">java-datapacks.md</a>: the Java Edition datapack format, Mojang&#39;s data generator reports, what Java keeps in code, Java worldgen as data, and the fit of Java data for a Bedrock server.</li><li><a href="/pr-preview/pr-3052/research/java-registries-and-components.html">java-registries-and-components.md</a>: all 60 datapack element registries with their reload and sync behavior, the item data component system from 1.20.5 to 26.3, loot and predicate composition, enchantments as data, registry sync in the configuration phase, pack format churn, and the boundary a datapack cannot cross.</li><li><a href="/pr-preview/pr-3052/research/java-code-only-behavior.html">java-code-only-behavior.md</a>: what Java holds in code now that 26.1 removed obfuscation, measured per area from the jar&#39;s line tables, with a 34-row table rating whether Bedrock data fills each gap.</li><li><a href="/pr-preview/pr-3052/research/commands-functions-and-datapack-execution.html">commands-functions-and-datapack-execution.md</a>: that vanilla ships no mcfunction files in either edition, the function runtime and its limits, the two editions&#39; command sets compared, and four defects in this repository&#39;s Brigadier port and command packet.</li></ul><h2 id="the-seam-between-them" tabindex="-1">The seam between them <a class="header-anchor" href="#the-seam-between-them" aria-label="Permalink to “The seam between them”">​</a></h2><ul><li><a href="/pr-preview/pr-3052/research/java-to-bedrock-translation.html">java-to-bedrock-translation.md</a>: whether Java-shaped state can be presented to a Bedrock client, measured against GeyserMC, per domain, with the losses counted and the license position stated.</li><li><a href="/pr-preview/pr-3052/research/hybrid-format-prior-art.html">hybrid-format-prior-art.md</a>: who has fused two content formats (nobody), Chunker and the other bidirectional mapping projects, the four candidate architectures compared, and the reusable mapping data sets with their licenses.</li><li><a href="/pr-preview/pr-3052/research/edition-behavior-differences.html">edition-behavior-differences.md</a>: 278 classified differences between the editions, each marked for who decides it and what happens if the server implements Java&#39;s version, plus a testable wording for the parity claim and the categories it must exclude.</li><li><a href="/pr-preview/pr-3052/research/storage-and-chunk-translation.html">storage-and-chunk-translation.md</a>: what this repository persists today, the Bedrock LevelDB format against Java&#39;s Anvil format, the cost of translating at the chunk boundary measured on this repository&#39;s code, and a storage recommendation.</li><li><a href="/pr-preview/pr-3052/research/cross-edition-worldgen-parity.html">cross-edition-worldgen-parity.md</a>: whether Java&#39;s published world generator produces Bedrock-identical worlds, the random number generator ceiling, structures, a verification method against a real server, and deepslate.</li></ul><h2 id="dimensions-and-portals" tabindex="-1">Dimensions and portals <a class="header-anchor" href="#dimensions-and-portals" aria-label="Permalink to “Dimensions and portals”">​</a></h2><ul><li><a href="/pr-preview/pr-3052/research/data-driven-dimensions.html">data-driven-dimensions.md</a>: Java&#39;s <code>dimension_type</code>, level stem, world preset and generator model in its 26.3 shape, Bedrock&#39;s integer ids, heights and 2026 custom dimensions, what this repository parses and sends today, six servers compared, and the design for a <code>DimensionType</code> registry, <code>LevelStem</code> per dimension, <code>GeneratorFactories</code> and one <code>Level</code> per save with the config migration.</li><li><a href="/pr-preview/pr-3052/research/dimension-storage-network-config.html">dimension-storage-network-config.md</a>: how LevelDB and Anvil address a dimension, the <code>level.dat</code>, player and entity fields a multi-dimension save needs, what the worker pool carries per pool and per task, the fourteen packets that name a dimension and which the server fills, the blast radius of splitting <code>World</code>, and the test order for a save and load round trip.</li><li><a href="/pr-preview/pr-3052/research/end-dragon-fight.html">end-dragon-fight.md</a>: the End dragon fight read from the 26.3 jar (fight state, spikes, crystals, dragon, podium, respawn stages, credits, gateways), the repo audit of what exists today, and the Bedrock wire mapping; executed by <a href="/pr-preview/pr-3052/plans/end-dragon-fight.html">docs/plans/end-dragon-fight.md</a>.</li><li><a href="/pr-preview/pr-3052/research/portals-and-dimension-travel.html">portals-and-dimension-travel.md</a>: nether portal frame, lighting, collapse, timers, cooldown, coordinate scaling, search and creation read from the 26.3 jar, end portal ring, platform and exit, the eight-step Bedrock dimension change sequence three reimplementations agree on, what the repository has, and the block-layer and server-layer design with its test plan.</li></ul><h2 id="method-and-prior-art" tabindex="-1">Method and prior art <a class="header-anchor" href="#method-and-prior-art" aria-label="Permalink to “Method and prior art”">​</a></h2><ul><li><a href="/pr-preview/pr-3052/research/move-actor-delta.html">move-actor-delta.md</a>: compressed MoveActorAbsolute and MoveActorDelta measurements over deterministic walking, idle, and farm-mob runtime traces, plus the decision to keep absolute movement packets.</li><li><a href="/pr-preview/pr-3052/research/packet-codec-enforcement.html">packet-codec-enforcement.md</a>: existing one-way packet codecs, enforcement options, and a fingerprinted legacy baseline.</li><li><a href="/pr-preview/pr-3052/research/protocol-2225-delta.html">protocol-2225-delta.md</a>: everything that changed on the wire between protocol 2193 and 2225 (Minecraft 1.26.60), verified against Mojang&#39;s release schemas and gophertunnel, with what <code>Codec2225</code> implements and what is still inherited from 2193.</li><li><a href="/pr-preview/pr-3052/research/sub-chunk-requests-and-blob-cache.html">sub-chunk-requests-and-blob-cache.md</a>: what <code>SubChunkPacket</code> and <code>LevelChunkPacket</code> carry when a client has its blob cache on, from Mojang&#39;s packet documentation, gophertunnel, dragonfly, Cloudburst and PocketMine&#39;s protocol library, against what this repository sent when a retail client left with a bad packet error.</li><li><a href="/pr-preview/pr-3052/research/protocol-2225-added-packets.html">protocol-2225-added-packets.md</a>: the field layout of the eight packets protocol 2225 added, read off the pinned v1.26.60 release schemas, with the <code>Compression</code>-means-varint and optional-field conventions they turn on.</li><li><a href="/pr-preview/pr-3052/research/packet-versioning-architectures.html">packet-versioning-architectures.md</a>: how to carry more protocol versions without transform chains or class sprawl, a taxonomy of real wire deltas, four candidate architectures compared against prior art, and the recommendation to keep the delta codec with a written pruning policy.</li><li><a href="/pr-preview/pr-3052/research/prior-art-data-driven-servers.html">prior-art-data-driven-servers.md</a>: how seventeen servers, engines and data projects model blocks, items and entities as data plus code, load packs and verify parity, with a pattern recommendation and reusable pieces.</li><li><a href="/pr-preview/pr-3052/research/engine-behavior-inventory.html">engine-behavior-inventory.md</a>: the behaviors a server must implement for 1463 blocks, 1623 items, 129 entities and the world, grouped into families with sizing.</li><li><a href="/pr-preview/pr-3052/research/extraction-and-parity-verification.html">extraction-and-parity-verification.md</a>: what the Script API and Endstone DevTools can dump, the extended packet capture, reference worlds, the parity test suite and caching.</li><li><a href="/pr-preview/pr-3052/research/bedrock-data-pipeline.html">bedrock-data-pipeline.md</a>: where every committed Bedrock artifact comes from and how to refresh it, as a per-artifact table, with what the capture already automates, the one manual artifact, the unreferenced files and the upstream and legal posture.</li><li><a href="/pr-preview/pr-3052/research/worldgen-pool-and-pipeline-architecture.html">worldgen-pool-and-pipeline-architecture.md</a>: how Moonrise, C2ME, Pumpkin and vanilla schedule, prioritize and isolate chunk generation, why Node cannot lower one worker&#39;s priority, a measured dispatch starvation experiment, and a generation host, work board and adaptive governor design.</li><li><a href="/pr-preview/pr-3052/research/scriptc-libdatachannel.html">scriptc-libdatachannel.md</a>: whether the NetherNet server&#39;s WebRTC backend can run on libdatachannel in a scriptc executable, with a measured FFI loopback over a statically linked libdatachannel, the Node island route that runs node-datachannel unchanged, the C API&#39;s coverage of what the server needs, a close probe, and a shim design.</li><li><a href="/pr-preview/pr-3052/research/nethernet-raknet-shared-port.html">nethernet-raknet-shared-port.md</a>: whether RakNet and NetherNet can share one UDP port number once NetherNet runs on libdatachannel, and RakNet&#39;s IPv4 and IPv6 listeners one number, with the first-byte classes of RakNet, query, STUN and DTLS, a loopback relay to libjuice run as a prototype with datagram counts, the kernel and upstream alternatives, the RakNet worker, and a recommended design with tests.</li><li><a href="/pr-preview/pr-3052/research/bds-server-udp-ports.html">bds-server-udp-ports.md</a>: what Bedrock Dedicated Server accepts in <code>server-udp-ports</code> and <code>server-public-ip</code> across three versions, with the 1.26.70.24 binary run against about 35 values, its errors, and the UDP sockets it opens for a single port, a range and the default.</li></ul></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};